138	\begin{lemma}[Product form and Pauli relations of the pulled-apart observables]\label{lem:tildew-product-form}
139		\lean{MIPStarRE.QPBT.tildeObs_eq_heteroKron}
140		\lean{MIPStarRE.QPBT.tildeObs_isHermitian}
141		\lean{MIPStarRE.QPBT.tildeObs_mul_self}
142		\lean{MIPStarRE.QPBT.tildeObs_twisted_commutation}
143		\leanok
144		\uses{def:tilde-w-observables, def:s-w-marginals, def:generalized-pauli, def:decoding-map, lem:qld-4-7}
145		Let $\tau^W(\cdot)$ denote the generalized Pauli $W$ observable (Definition~\ref{def:generalized-pauli}). For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^M$, and $j \in \{0,\ldots,t-1\}$,
146		\begin{equation}\label{eq:tildewj-product-form}
147			\tilde{W}^j(\tilde{u})
148			= \Big( \sum_{g_X,g_Z} (-1)^{\tr(e_j (\mathrm{Dec}(g_W) \cdot \tilde{u}))} \, \hat{S}_{g_X,g_Z} \Big) \ot \tau^W(e_j \tilde{u})\;,
149		\end{equation}
150		where $g_W$ denotes $g_X$ if $W = X$ and $g_Z$ if $W = Z$. In particular each $\tilde{W}^j(\tilde{u})$ is Hermitian and squares to the identity. Moreover, the pulled-apart observables satisfy exactly the twisted commutation relations of the generalized Pauli observables $\tau^X(e_j \tilde{u})$ and $\tau^Z(e_{j'} \tilde{v})$: for all $j,j' \in \{1,\ldots,t\}$ and $\tilde{u},\tilde{v} \in \F_q^M$,
151		\begin{equation}\label{eq:tildew-twisted-commutation}
152			\tilde{X}^j(\tilde{u})\, \tilde{Z}^{j'}(\tilde{v})
153			= (-1)^{\tr((e_j \tilde{u}) \cdot (e_{j'} \tilde{v}))}\, \tilde{Z}^{j'}(\tilde{v})\, \tilde{X}^j(\tilde{u})\;,
154		\end{equation}
155		where $\tr((e_j \tilde{u}) \cdot (e_{j'} \tilde{v})) = \tr(e_j e_{j'} (\tilde{u} \cdot \tilde{v}))$.
156	\end{lemma}
157	\begin{proof}
158		\uses{def:tilde-w-observables, def:tilde-m-measurement, def:tau-dot-product-projector, def:s-w-marginals, lem:pauli-observable-expansion, lem:twisted-commutation, lem:qld-4-7}
159		Expanding $\tau^W(e_j \tilde{u}) = \sum_{h} (-1)^{\tr(e_j (\tilde{u} \cdot h))}\, \tau^W_h$ on the right-hand side of \eqref{eq:tildewj-product-form} (Lemma~\ref{lem:pauli-observable-expansion}), grouping the $h$ according to the value $a' = h \cdot \tilde{u}$ into the projectors $\tau^W_{a'}(\tilde{u})$ of \eqref{eq:def-tauwu}, collecting the pairs $(g_X,g_Z)$ with a common value $g_W = g$ into $\hat{S}^W_g$ (Definition~\ref{def:s-w-marginals}), and changing the summation variable to $a = (\mathrm{Dec}(g) \cdot \tilde{u}) - a'$ recovers, by \eqref{eq:tilde_M} and \eqref{eq:def-tildewj}, the operator $\tilde{W}^j(\tilde{u})$; this proves \eqref{eq:tildewj-product-form}. Since the $\hat{S}_{g_X,g_Z}$ are mutually orthogonal projectors summing to the identity (Lemma~\ref{lem:qld-4-7}) and $\tau^W(e_j \tilde{u})$ is a Hermitian involution, the product form exhibits $\tilde{W}^j(\tilde{u})$ as Hermitian with square $\sum_{g_X,g_Z} \hat{S}_{g_X,g_Z} \ot \Id = \Id$. For \eqref{eq:tildew-twisted-commutation}, the two sign-weighted sums of the projectors $\hat{S}_{g_X,g_Z}$ appearing in the product forms of $\tilde{X}^j(\tilde{u})$ and $\tilde{Z}^{j'}(\tilde{v})$ commute with each other, so the commutation phase is that of $\tau^X(e_j \tilde{u})$ and $\tau^Z(e_{j'} \tilde{v})$, which is $(-1)^{\tr((e_j \tilde{u}) \cdot (e_{j'} \tilde{v}))}$ by Lemma~\ref{lem:twisted-commutation}.
160	\end{proof}
